private.reference_solution:
#include <iostream>
#include <string>

int main() {
    std::string line;
    if (!std::getline(std::cin, line)) return 1;
    try {
        std::size_t pos = 0;
        int n = std::stoi(line, &pos);
        if (pos != line.size()) return 1;
        if (n < 0 || n > 100000) return 1;
        long long sum = 0;
        for (int i = 1; i <= n; i++) sum += i;
        std::cout << sum << std::endl;
        return 0;
    } catch (...) {
        return 1;
    }
}
